150	// countFindingsByTab returns the count of findings for each tab
151	func (m *Model) countFindingsByTab() (cve, secrets, licenses, misconfigs int) {
152		if m.result == nil {
153			return 0, 0, 0, 0
154		}
155	
156		for _, f := range m.result.Findings {
157			switch {
158			case f.Source == "trivy" && f.PkgName != "" && f.Match == "":
159				cve++
160			case f.Source == "gitleaks" || (f.Source == "trivy" && f.Match != ""):
161				secrets++
162			case f.Source == "trivy-license":
163				licenses++
164			case f.Source == "trivy-misconfig":
165				misconfigs++
166			}
167		}
168		return cve, secrets, licenses, misconfigs
169	}
170	
171	// switchTab switches to the given tab index and refreshes the table
172	func (m *Model) switchTab(tab int) {
173		m.activeTab = tab
174		m.statusMessage = ""
175		m.updateFindingsTable()
176	}
