41	// Each tab is a different question about the same findings, so the routing is
42	// what makes the counts mean anything.
43	func TestEachTabShowsItsOwnFindings(t *testing.T) {
44		tests := []struct {
45			tab  int
46			want []string
47		}{
48			{TabCVE, []string{"CVE-2026-0001", "CVE-2026-0002"}},
