74	func TestTabKeysAndCycling(t *testing.T) {
75		m := scannedModel(t)
76	
77		for key, want := range map[string]int{"1": TabCVE, "2": TabSecrets, "3": TabLicense, "4": TabMisconfig} {
78			if got := feed(t, m, testutil.Key(key)).activeTab; got != want {
79				t.Errorf("%q selected tab %d, want %d", key, got, want)
80			}
81		}
82	
83		m = feed(t, m, testutil.Key("tab"))
84		if m.activeTab != TabSecrets {
85			t.Errorf("tab moved to %d, want the next one", m.activeTab)
86		}
87	
88		m = feed(t, m, testutil.Key("shift+tab"))
89		if m.activeTab != TabCVE {
90			t.Errorf("shift+tab moved to %d, want back to the first", m.activeTab)
91		}
92	
93		// Cycling wraps rather than stopping at the last tab.
94		m = feed(t, m, testutil.Keys("tab", "tab", "tab", "tab")...)
95		if m.activeTab != TabCVE {
96			t.Errorf("a full cycle ended on tab %d", m.activeTab)
97		}
