31				want:    []string{"tab", "enter", ".", "ctrl+r"},
32				notWant: []string{"i", "space"},
33			},
34			{
35				// '.' has no severity axis on secrets and 'i' has nothing to ignore
36				// anywhere else, so the two swap.
37				name: "the secrets tab",
38				open: func(t *testing.T) Model {
39					m := scannedModel(t)
40					m.switchTab(TabSecrets)
41					return m
42				},
