47				name:    "the details",
48				open:    func(t *testing.T) Model { return detailsModel(t) },
49				want:    []string{"esc/⌫", "o"},
50				notWant: []string{"tab", "ctrl+r"},
51			},
52		}
53	
54		for _, tt := range tests {
55			t.Run(tt.name, func(t *testing.T) {
56				keys := map[string]bool{}
57				for _, s := range tt.open(t).GetShortcuts() {
58					keys[s.Key] = true
59				}
60				for _, key := range tt.want {
61					if !keys[key] {
62						t.Errorf("%q is not advertised", key)
63					}
64				}
65				for _, key := range tt.notWant {
66					if keys[key] {
67						t.Errorf("%q is advertised but cannot run here", key)
