package scan

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"strings"
)

// TrivyReport represents the JSON output from Trivy
type TrivyReport struct {
	Results []TrivyResult `json:"Results"`
}

// TrivyResult represents a single result from Trivy
type TrivyResult struct {
	Target            string                  `json:"Target"`
	Class             string                  `json:"Class"`
	Type              string                  `json:"Type"`
	Vulnerabilities   []TrivyVulnerability    `json:"Vulnerabilities"`
	Secrets           []TrivySecret           `json:"Secrets,omitempty"`
	Licenses          []TrivyLicense          `json:"Licenses,omitempty"`
	Misconfigurations []TrivyMisconfiguration `json:"Misconfigurations,omitempty"`
}

// TrivyVulnerability represents a vulnerability found by Trivy
type TrivyVulnerability struct {
	VulnerabilityID  string   `json:"VulnerabilityID"`
	PkgName          string   `json:"PkgName"`
	InstalledVersion string   `json:"InstalledVersion"`
	FixedVersion     string   `json:"FixedVersion"`
	Severity         string   `json:"Severity"`
	Title            string   `json:"Title"`
	Description      string   `json:"Description"`
	PrimaryURL       string   `json:"PrimaryURL,omitempty"`
	References       []string `json:"References,omitempty"`
}

// TrivySecret represents a secret found by Trivy
type TrivySecret struct {
	RuleID    string `json:"RuleID"`
	Category  string `json:"Category"`
	Severity  string `json:"Severity"`
	Title     string `json:"Title"`
	StartLine int    `json:"StartLine"`
	EndLine   int    `json:"EndLine"`
	Match     string `json:"Match"`
}

// TrivyLicense represents a license found by Trivy
type TrivyLicense struct {
	Severity   string  `json:"Severity"`
	Category   string  `json:"Category"` // forbidden, restricted, reciprocal, notice, permissive, unencumbered, unknown
	PkgName    string  `json:"PkgName"`
	FilePath   string  `json:"FilePath"`
	Name       string  `json:"Name"` // License identifier (SPDX): MIT, Apache-2.0, GPL-3.0, etc.
	Confidence float64 `json:"Confidence"`
	Link       string  `json:"Link"`
}

// TrivyMisconfiguration represents a misconfiguration found by Trivy
type TrivyMisconfiguration struct {
	Type          string `json:"Type"`
	ID            string `json:"ID"`
	AVDID         string `json:"AVDID"`
	Title         string `json:"Title"`
	Desc          string `json:"Description"`
	Message       string `json:"Message"`
	Severity      string `json:"Severity"`
	Resolution    string `json:"Resolution"`
	PrimaryURL    string `json:"PrimaryURL"`
	Status        string `json:"Status"`
	CauseMetadata struct {
		StartLine int `json:"StartLine"`
		EndLine   int `json:"EndLine"`
	} `json:"CauseMetadata"`
}

// RunTrivy executes Trivy and returns findings.
// progressFn is an optional callback called with each stderr line (DB download progress etc.).
func RunTrivy(ctx context.Context, target string, targetType TargetType, licenseMode bool, tool ToolSpec, server string, ignoreUnfixed bool, ignoreEOL bool, progressFn func(string)) ([]Finding, error) {
	tc, err := trivyArgs(target, targetType, licenseMode, tool, server, ignoreUnfixed, ignoreEOL)
	if err != nil {
		return nil, err
	}
	return runTrivy(ctx, tc, progressFn)
}

// runTrivy executes a built invocation and parses what it wrote to stdout.
//
// A non-zero exit is not on its own a failure: Trivy exits 1 when it finds
// vulnerabilities, and the report on stdout is exactly what the caller asked
// for. Only an exit that produced no report is reported as an error.
func runTrivy(ctx context.Context, tc toolCmd, progressFn func(string)) ([]Finding, error) {
	stdout, err := runner.Run(ctx, tc, progressFn)
	if err != nil {
		var exit *exitError
		if !errors.As(err, &exit) || len(stdout) == 0 {
			return nil, fmt.Errorf("trivy failed: %w", err)
		}
	}
	return parseTrivyOutput(stdout)
}

// parseTrivyOutput parses Trivy JSON output into findings
func parseTrivyOutput(data []byte) ([]Finding, error) {
	var report TrivyReport
	if err := json.Unmarshal(data, &report); err != nil {
		return nil, fmt.Errorf("failed to parse trivy output: %w", err)
	}

	var findings []Finding

	for _, result := range report.Results {
		// Process vulnerabilities
		for _, vuln := range result.Vulnerabilities {
			// Build references from PrimaryURL and advisory links
			refs := make([]string, 0, len(vuln.References)+1)
			if vuln.PrimaryURL != "" {
				refs = append(refs, vuln.PrimaryURL)
			}
			for _, r := range vuln.References {
				if r != vuln.PrimaryURL {
					refs = append(refs, r)
				}
			}

			// Build a fix command suggestion when a fixed version is known
			fixCmd := ""
			if vuln.FixedVersion != "" {
				fixCmd = fmt.Sprintf("Update %s to %s", vuln.PkgName, vuln.FixedVersion)
			}

			findings = append(findings, Finding{
				ID:          vuln.VulnerabilityID,
				Title:       vuln.Title,
				Description: vuln.Description,
				Severity:    parseSeverity(vuln.Severity),
				Source:      "trivy",
				File:        result.Target,
				PkgName:     vuln.PkgName,
				Version:     vuln.InstalledVersion,
				FixedIn:     vuln.FixedVersion,
				References:  refs,
				FixCommand:  fixCmd,
			})
		}

		// Process secrets found by Trivy.
		//
		// The report has carried these since TrivySecret was declared; nothing
		// read them, so a secret Trivy found was parsed and dropped. Only the
		// secret stage asks for them (--scanners secret), so there is no risk of
		// the vulnerability stage returning the same finding twice.
		for _, secret := range result.Secrets {
			findings = append(findings, Finding{
				ID:          secret.RuleID,
				Title:       secret.Title,
				Description: secret.Category,
				Severity:    parseSeverity(secret.Severity),
				Source:      SourceTrivySecret,
				File:        result.Target,
				Line:        secret.StartLine,
				Match:       maskSecret(secret.Match),
			})
		}

		// Process licenses found by Trivy
		for _, license := range result.Licenses {
			findings = append(findings, Finding{
				ID:          license.Name,
				Title:       fmt.Sprintf("%s (%s)", license.PkgName, license.Name),
				Description: fmt.Sprintf("License category: %s", license.Category),
				Severity:    parseSeverity(license.Severity),
				Source:      "trivy-license",
				File:        license.FilePath,
				PkgName:     license.PkgName,
			})
		}

		// Process misconfigurations found by Trivy
		for _, misconf := range result.Misconfigurations {
			var miscRefs []string
			if misconf.PrimaryURL != "" {
				miscRefs = append(miscRefs, misconf.PrimaryURL)
			}
			findings = append(findings, Finding{
				ID:          misconf.AVDID,
				Title:       misconf.Title,
				Description: misconf.Desc,
				Severity:    parseSeverity(misconf.Severity),
				Source:      "trivy-misconfig",
				File:        result.Target,
				Line:        misconf.CauseMetadata.StartLine,
				Resolution:  misconf.Resolution,
				References:  miscRefs,
			})
		}
	}

	return findings, nil
}

// parseSeverity converts string severity to SeverityLevel
func parseSeverity(s string) SeverityLevel {
	switch strings.ToUpper(s) {
	case "CRITICAL":
		return SeverityCritical
	case "HIGH":
		return SeverityHigh
	case "MEDIUM":
		return SeverityMedium
	case "LOW":
		return SeverityLow
	default:
		return SeverityUnknown
	}
}

// maskSecret partially masks secret values for display
func maskSecret(s string) string {
	if len(s) <= 8 {
		return "****"
	}
	return s[:4] + "****" + s[len(s)-4:]
}

// GetTrivyCommand returns the command that would be executed, for display and
// logging. It is built by the same builder as the executed command, so the two
// cannot drift apart.
func GetTrivyCommand(target string, targetType TargetType, licenseMode bool, tool ToolSpec, server string, ignoreUnfixed bool, ignoreEOL bool) string {
	tc, err := trivyArgs(target, targetType, licenseMode, tool, server, ignoreUnfixed, ignoreEOL)
	if err != nil {
		return ""
	}
	return tc.String()
}

// GetTrivySecretCommand returns the secret scan command for display.
func GetTrivySecretCommand(target string, targetType TargetType, tool ToolSpec, server string) string {
	tc, err := trivySecretArgs(target, targetType, tool, server)
	if err != nil {
		return ""
	}
	return tc.String()
}

// RunTrivySecret executes Trivy with --scanners secret and returns findings.
// progressFn is an optional callback called with each stderr line.
func RunTrivySecret(ctx context.Context, target string, targetType TargetType, tool ToolSpec, server string, progressFn func(string)) ([]Finding, error) {
	tc, err := trivySecretArgs(target, targetType, tool, server)
	if err != nil {
		return nil, err
	}
	return runTrivy(ctx, tc, progressFn)
}

// GetTrivyMisconfigCommand returns the misconfiguration scan command for display.
func GetTrivyMisconfigCommand(target string, targetType TargetType, tool ToolSpec, server string, ignoreEOL bool) string {
	tc, err := trivyMisconfigArgs(target, targetType, tool, server, ignoreEOL)
	if err != nil {
		return ""
	}
	return tc.String()
}

// RunTrivyMisconfig executes Trivy with --scanners misconfig and returns findings.
// progressFn is an optional callback called with each stderr line.
func RunTrivyMisconfig(ctx context.Context, target string, targetType TargetType, tool ToolSpec, server string, ignoreEOL bool, progressFn func(string)) ([]Finding, error) {
	tc, err := trivyMisconfigArgs(target, targetType, tool, server, ignoreEOL)
	if err != nil {
		return nil, err
	}
	return runTrivy(ctx, tc, progressFn)
}

package security

import (
	"strings"
	"testing"

	"github.com/anthnel/devdesk/internal/ui/testutil"
)

// Trivy and Gitleaks write a wall of structured log lines to stderr. The point
// of this layer is that the panel shows the one line that explains the failure
// rather than the wall, so these tests are all about what gets discarded.

func TestParseScanErrorSplitsSourceFromDetail(t *testing.T) {
	source, detail := parseScanError("trivy vuln: trivy failed: 2026-08-01T10:00:00Z\tFATAL\trun error: image not found")

	if source != "trivy vuln" {
		t.Errorf("source = %q, want the scanner that failed", source)
	}
	if detail != "Error : image not found" {
		t.Errorf("detail = %q, want the message alone", detail)
	}
}

// Each scanner wraps its own error differently; the intermediate "<tool>
// failed:" prefix carries nothing the source label does not already say.
func TestParseScanErrorStripsEveryToolPrefix(t *testing.T) {
	prefixes := []string{
		"trivy failed: ",
		"trivy misconfig failed: ",
		"gitleaks failed: ",
	}

	for _, prefix := range prefixes {
		_, detail := parseScanError("some source: " + prefix + "the real problem")

		if detail != "the real problem" {
			t.Errorf("with prefix %q, detail = %q", prefix, detail)
		}
	}
}

// A message with no source label is still shown rather than dropped.
func TestParseScanErrorWithoutASource(t *testing.T) {
	source, detail := parseScanError("docker daemon unreachable")

	if source != "" {
		t.Errorf("source = %q, want none", source)
	}
	if detail != "docker daemon unreachable" {
		t.Errorf("detail = %q", detail)
	}
}

func TestExtractMeaningfulLines(t *testing.T) {
	tests := []struct {
		name string
		in   string
		want string
	}{
		{
			name: "INFO lines are discarded",
			in: "2026-08-01T10:00:00Z\tINFO\tVulnerability scanning is enabled\n" +
				"2026-08-01T10:00:01Z\tERROR\tdb download failed",
			want: "Error : db download failed",
		},
		{
			name: "WARN and WARNING are both kept",
			in: "2026-08-01T10:00:00Z\tWARN\tfirst\n" +
				"2026-08-01T10:00:01Z\tWARNING\tsecond",
			want: "Error : first\nError : second",
		},
		{
			name: "multi-space separators work like tabs",
			in:   "2026-08-01T10:00:00Z   ERROR   logrus style",
			want: "Error : logrus style",
		},
		{
			name: "progress bars are discarded",
			in: "12.34 MiB / 45.67 MiB [-----] 27%\n" +
				"[--- downloading ---]\n" +
				"1.2 p/s eta 3s\n" +
				"2026-08-01T10:00:00Z\tERROR\tthe actual failure",
			want: "Error : the actual failure",
		},
		{
			name: "unstructured lines are kept verbatim",
			in:   "exit status 1\nsomething went wrong",
			want: "exit status 1\nsomething went wrong",
		},
		{
			name: "blank lines are dropped",
			in:   "first\n\n   \nsecond",
			want: "first\nsecond",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := extractMeaningfulLines(tt.in); got != tt.want {
				t.Errorf("extractMeaningfulLines() =\n%q\nwant\n%q", got, tt.want)
			}
		})
	}
}

// Discarding everything would leave the user with an empty panel and no idea
// why the scan failed, so the raw text comes back instead.
func TestExtractMeaningfulLinesFallsBackToTheOriginal(t *testing.T) {
	onlyInfo := "2026-08-01T10:00:00Z\tINFO\tnothing interesting"

	if got := extractMeaningfulLines(onlyInfo); got != onlyInfo {
		t.Errorf("extractMeaningfulLines() = %q, want the original text", got)
	}
}

// Trivy wraps its fatal errors twice; the panel shows the innermost message.
func TestFatalLinesAreUnwrapped(t *testing.T) {
	tests := []struct {
		name    string
		level   string
		message string
		want    string
	}{
		{"run error", "FATAL", "Fatal error\trun error: image not found", "Error : image not found"},
		{"no run error", "FATAL", "Fatal error\tsomething else", "Error : something else"},
		{"not fatal", "ERROR", "left alone", "Error : left alone"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := formatScanErrorLine(tt.level, tt.message); got != tt.want {
				t.Errorf("formatScanErrorLine() = %q, want %q", got, tt.want)
			}
		})
	}
}

func TestSplitLogLine(t *testing.T) {
	tests := []struct {
		name        string
		line        string
		wantLevel   string
		wantMessage string
	}{
		{"tab separated", "2026-08-01T10:00:00Z\tERROR\tthe message", "ERROR", "the message"},
		{"space separated", "2026-08-01T10:00:00Z   ERROR   the message", "ERROR", "the message"},
		{"level with no message", "2026-08-01T10:00:00Z\tERROR", "ERROR", ""},
		{"no separator at all", "2026-08-01T10:00:00Z", "", "2026-08-01T10:00:00Z"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			level, message := splitLogLine(tt.line)

			if level != tt.wantLevel || message != tt.wantMessage {
				t.Errorf("splitLogLine() = (%q, %q), want (%q, %q)", level, message, tt.wantLevel, tt.wantMessage)
			}
		})
	}
}

// ── The panel ────────────────────────────────────────────────────────────────

// Warnings replace the table rather than sitting above it: a scan that failed
// has no partial findings worth browsing, and the tab bar would suggest it did.
func TestWarningsReplaceTheTable(t *testing.T) {
	result := resultFixture()
	result.Errors = []string{"trivy vuln: trivy failed: 2026-08-01T10:00:00Z\tFATAL\trun error: image not found"}

	m := feed(t, NewWithPreloadedResult(testConfig(), result), testutil.Resize(160, 30))

	view := m.View()
	if !strings.Contains(view, "Scan Warnings") {
		t.Errorf("the warnings panel is not shown:\n%s", view)
	}
	if !strings.Contains(view, "image not found") {
		t.Error("the panel does not show the parsed failure")
	}
	if !strings.Contains(view, "trivy vuln") {
		t.Error("the panel does not name the scanner that failed")
	}
	if strings.Contains(view, "CVE-2026-0001") {
		t.Error("the findings table is rendered behind the warnings")
	}
}

// Rule 124: no tab bar when warnings replace the table, so the footer is two
// lines rather than three.
func TestWarningsShrinkTheFooter(t *testing.T) {
	result := resultFixture()
	result.Errors = []string{"trivy: failed"}
	m := feed(t, NewWithPreloadedResult(testConfig(), result), testutil.Resize(160, 30))

	if got := m.GetFooterHeight(); got != 2 {
		t.Errorf("GetFooterHeight() = %d with warnings, want 2", got)
	}
	if lines := strings.Count(m.RenderFooter(160), "\n") + 1; lines != 2 {
		t.Errorf("RenderFooter() emitted %d lines", lines)
	}
}

package security

import (
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"time"

	"github.com/anthnel/devdesk/internal/scan"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// targetKind tells the two caches apart. It decides which loader `enter` uses
// and which TargetType a rescan runs with, so it is carried rather than
// re-derived from the name — an absolute path and a "repo:tag" are not reliably
// distinguishable, and guessing wrong scans a directory as an image.
type targetKind int

const (
	kindImage targetKind = iota
	kindRepo
)

// scanTarget is one row of the inventory: something that has been scanned, what
// the scan found, and when.
//
// Kind, the display name and whether a rescan is running now live on none of
// the cache entries, which is why the decoration goes on the row rather than
// being looked up from the model — the same reason imageRow exists. The columns
// are built once, in New, so their Cell functions have nothing to reach back
// into, and each count column sorts by the number it prints.
type scanTarget struct {
	Kind      targetKind
	Name      string // the cache key: "repo:tag", or the absolute repository path
	Counts    scan.SeverityCounts
	ScannedAt time.Time
	// Scanned is false between a ctrl+a purge and the scan that replaces it.
	// The target is still known — it is the counts that are not.
	Scanned      bool
	Scanning     bool
	Failed       bool
	SpinnerFrame string
}

// inventoryColumnCritical is the column the inventory opens sorted by,
// descending: the target with the most critical findings is the one the view
// exists to surface.
const inventoryColumnCritical = 1

// displayName is what the Target column shows: the image reference as it is
// cached, or the repository path with the home directory folded back to "~".
// The cache key stays the value everything else uses, so folding here cannot
// reach a loader or a scanner.
func (t scanTarget) displayName() string {
	if t.Kind == kindImage {
		return theme.IconDocker + " " + t.Name
	}
	return theme.IconWorkspace + " " + shortenHome(t.Name)
}

// shortenHome replaces the home directory prefix with "~". It is the inverse of
// the expansion the workspaces view does on the configured root.
func shortenHome(path string) string {
	home, err := os.UserHomeDir()
	if err != nil || home == "" {
		return path
	}
	rel, err := filepath.Rel(home, path)
	if err != nil || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
		return path
	}
	if rel == "." {
		return "~"
	}
	return "~" + string(filepath.Separator) + rel
}

// countColumnWidth holds the four severity columns to one width. datatable
// already reserves room for the sort arrow, which would give CRIT and HIGH six
// cells and MED and LOW five — four adjacent columns of the same kind, ragged.
const countColumnWidth = 6

// countColumn builds one of the four severity columns. A purged row prints "-"
// rather than "0": nothing was found and nothing is known are different answers,
// and zero is the one a user reads as "clean".
func countColumn(title string, get func(scan.SeverityCounts) int) datatable.Column[scanTarget] {
	return datatable.Column[scanTarget]{
		Title: title, MinWidth: countColumnWidth,
		Cell: func(t scanTarget) string {
			if !t.Scanned {
				return "-"
			}
			return strconv.Itoa(get(t.Counts))
		},
		Less: func(a, b scanTarget) bool { return get(a.Counts) < get(b.Counts) },
	}
}

// inventoryScannedCell reports the scan state: the spinner while one runs, an
// error icon when the last attempt failed, otherwise how long ago it succeeded
// (Rule 127). Plain text throughout — Rule 122.
func inventoryScannedCell(t scanTarget) string {
	switch {
	case t.Scanning:
		return t.SpinnerFrame + "scanning"
	case t.Failed:
		return theme.IconError + " error"
	case t.Scanned:
		return theme.TimeAgo(t.ScannedAt)
	}
	return "-"
}

// inventoryColumns describes the inventory table.
func inventoryColumns() []datatable.Column[scanTarget] {
	return []datatable.Column[scanTarget]{
		{
			Title: "Target", MinWidth: 24, Flex: 1,
			Cell: func(t scanTarget) string { return t.displayName() },
			Less: func(a, b scanTarget) bool {
				return strings.ToLower(a.Name) < strings.ToLower(b.Name)
			},
			// The cache key, not the displayed name: a query for the full path of
			// a repository has to match the row that folds it to "~".
			Search: func(t scanTarget) string { return t.Name },
		},
		countColumn("CRIT", func(c scan.SeverityCounts) int { return c.Critical }),
		countColumn("HIGH", func(c scan.SeverityCounts) int { return c.High }),
		countColumn("MED", func(c scan.SeverityCounts) int { return c.Medium }),
		countColumn("LOW", func(c scan.SeverityCounts) int { return c.Low }),
		{
			Title: "Scanned", MinWidth: 14,
			Cell: inventoryScannedCell,
			Less: func(a, b scanTarget) bool { return a.ScannedAt.Before(b.ScannedAt) },
		},
	}
}

// newInventoryTable builds the inventory table.
func newInventoryTable() datatable.Model[scanTarget] {
	return datatable.New(datatable.Config[scanTarget]{
		Columns:    inventoryColumns(),
		SortColumn: inventoryColumnCritical,
		SortDesc:   true,
	})
}

